// src/App.js — khai báo MỌI route của CodeLearn ở một chỗ (nhìn là thấy cả sơ đồ trang)
import { Navigate, Route, Routes } from 'react-router-dom';
import Layout from './components/Layout';
import HomePage from './pages/HomePage';
import CoursesPage from './pages/CoursesPage';
import NotFoundPage from './pages/NotFoundPage';
import ProtectedRoute from './components/ProtectedRoute';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import AdminLayout from './pages/admin/AdminLayout';
import CourseDetailPage from './pages/CourseDetailPage';
import MyCoursesPage from './pages/MyCoursesPage';
import LearnPage from './pages/LearnPage';
import QuizPage from './pages/QuizPage';
import ProgressPage from './pages/ProgressPage';
import AdminCoursesPage from './pages/admin/AdminCoursesPage';
import CourseFormPage from './pages/admin/CourseFormPage';
import CurriculumPage from './pages/admin/CurriculumPage';
import AdminQuestionsPage from './pages/admin/AdminQuestionsPage';
import AdminUsersPage from './pages/admin/AdminUsersPage';

export default function App() {
  return (
    <Routes>
      {/* Layout chung: navbar + <Outlet /> + footer cho mọi trang */}
      <Route element={<Layout />}>
        {/* ── Khách (guest) xem được ── */}
        <Route path="/" element={<HomePage />} />
        <Route path="/courses" element={<CoursesPage />} />
        <Route path="/courses/:id" element={<CourseDetailPage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />

        {/* ── Phải đăng nhập (học viên) ── */}
        <Route element={<ProtectedRoute />}>
          <Route path="/my-courses" element={<MyCoursesPage />} />
          <Route path="/learn/:courseId" element={<LearnPage />} />
          <Route path="/learn/:courseId/lessons/:lessonId" element={<LearnPage />} />
          <Route path="/quiz/:chapterId" element={<QuizPage />} />
          <Route path="/progress" element={<ProgressPage />} />
        </Route>

        {/* ── Chỉ ADMIN — route lồng: AdminLayout có sidebar + <Outlet /> ── */}
        <Route path="/admin" element={<ProtectedRoute role="admin"><AdminLayout /></ProtectedRoute>}>
          <Route index element={<Navigate to="courses" replace />} />
          <Route path="courses" element={<AdminCoursesPage />} />
          <Route path="courses/new" element={<CourseFormPage />} />
          <Route path="courses/:id/edit" element={<CourseFormPage />} />
          <Route path="courses/:id/curriculum" element={<CurriculumPage />} />
          <Route path="questions" element={<AdminQuestionsPage />} />
          <Route path="users" element={<AdminUsersPage />} />
        </Route>

        {/* Mọi đường dẫn không khớp ⇒ 404 (luôn để CUỐI) */}
        <Route path="*" element={<NotFoundPage />} />
      </Route>
    </Routes>
  );
}

// src/api/quizApi.js — questions + results (mọi hàm trả response.data)
// ⚠ json-server trả cả answerIndex về trình duyệt — máy chủ thật phải chấm ở server và giấu đáp án.
import axiosClient from './axiosClient';

const quizApi = {
  getChapter: (id) => axiosClient.get(`/chapters/${id}`).then((res) => res.data),
  getQuestions: (chapterId) => axiosClient.get('/questions', { params: { chapterId, _sort: 'id' } }).then((res) => res.data),
  saveResult: (result) => axiosClient.post('/results', result).then((res) => res.data),
  // lịch sử làm bài của MỘT học viên, kèm tên chương (_expand=chapter), mới nhất trước
  getResultsByUser: (userId) =>
    axiosClient.get('/results', { params: { userId, _expand: 'chapter', _sort: 'submittedAt', _order: 'desc' } }).then((res) => res.data),
  getByCourse: (courseId) => axiosClient.get('/questions', { params: { courseId } }).then((res) => res.data),
  // ── admin ──
  createQuestion: (question) => axiosClient.post('/questions', question).then((res) => res.data),
  updateQuestion: (id, question) => axiosClient.put(`/questions/${id}`, question).then((res) => res.data),
  deleteQuestion: (id) => axiosClient.delete(`/questions/${id}`).then((res) => res.data),
  deleteResult: (id) => axiosClient.delete(`/results/${id}`).then((res) => res.data),
};

export default quizApi;

// src/pages/admin/AdminLayout.js — khung khu quản trị (route lồng: các trang admin hiện ở <Outlet />)
import { Col, Nav, Row } from 'react-bootstrap';
import { NavLink, Outlet } from 'react-router-dom';

export default function AdminLayout() {
  return (
    <Row>
      <Col md={3} lg={2} className="mb-3">
        <div className="admin-sidebar bg-white rounded-3 shadow-sm p-2">
          <div className="fw-bold small text-uppercase text-muted px-2 py-1">Admin</div>
          <Nav className="flex-column">
            <Nav.Link as={NavLink} to="/admin/courses" id="admin-nav-courses">Courses</Nav.Link>
            <Nav.Link as={NavLink} to="/admin/questions" id="admin-nav-questions">Quiz questions</Nav.Link>
            <Nav.Link as={NavLink} to="/admin/users" id="admin-nav-users">Users</Nav.Link>
          </Nav>
        </div>
      </Col>
      <Col md={9} lg={10}>
        <Outlet />
      </Col>
    </Row>
  );
}

