      {status === 'succeeded' && items.length === 0 && (
        <Alert variant="info" id="no-enrollments">
          You have not enrolled in any course yet. <Link to="/courses">Browse courses</Link>
        </Alert>
      )}
      <Row xs={1} md={2} lg={3} className="g-3">
