                </Card.Body>
                <Card.Footer className="bg-white">
                  <Link className="btn btn-primary btn-sm btn-continue" to={`/learn/${e.courseId}`}>Continue learning</Link>
                </Card.Footer>
              </Card>
            </Col>
          );
        })}
      </Row>
    </>
  );
}

