// src/components/ProtectedRoute.js — chặn route theo đăng nhập và vai trò
//   <Route element={<ProtectedRoute />}> … </Route>                    ⇒ phải đăng nhập
//   <ProtectedRoute role="admin"><AdminLayout /></ProtectedRoute>      ⇒ phải là admin
import { Alert } from 'react-bootstrap';
import { useSelector } from 'react-redux';
import { Navigate, Outlet, useLocation } from 'react-router-dom';
import { selectUser } from '../features/auth/authSlice';

export default function ProtectedRoute({ role, children }) {
  const user = useSelector(selectUser);
  const location = useLocation();

  // Chưa đăng nhập ⇒ sang /login, NHỚ trang đang muốn vào (state.from) để đăng nhập xong quay lại.
  // replace: nút Back không đưa người dùng về trang bị chặn rồi bị đẩy đi lần nữa.
  if (!user) return <Navigate to="/login" replace state={{ from: location }} />;

  // Đăng nhập rồi nhưng sai vai trò ⇒ 403 (không phải 404, không phải đá về /login)
  if (role && user.role !== role) {
    return (
      <Alert variant="danger" id="forbidden" className="mt-3">
        <Alert.Heading>403 — Access denied</Alert.Heading>
        <p className="mb-0">This page is for administrators only.</p>
      </Alert>
    );
  }

  return children ?? <Outlet />;
}

// src/features/auth/authSlice.js — đăng nhập / đăng ký trên bảng users của json-server + phiên trong localStorage
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import authApi from '../../api/authApi';
import { todayISO } from '../../utils/format';

export const STORAGE_KEY = 'codelearn_user';

// Đọc phiên cũ MỘT lần khi tạo store. Dữ liệu hỏng/không có ⇒ null (không làm sập app).
function loadUser() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

// Không bao giờ giữ mật khẩu trong Redux hay localStorage
const withoutPassword = ({ password, ...user }) => user;

export const login = createAsyncThunk('auth/login', async ({ email, password }, { rejectWithValue }) => {
  const users = await authApi.findByEmail(email.trim().toLowerCase());
  const user = users.find((u) => u.password === password);
  // cùng một thông điệp cho "sai email" và "sai mật khẩu" — không tiết lộ email nào đã có tài khoản
  if (!user) return rejectWithValue('Invalid email or password');
  if (user.active === false) return rejectWithValue('Your account has been locked. Please contact the admin.');
  return withoutPassword(user);
});

export const register = createAsyncThunk('auth/register', async ({ fullName, email, password }, { rejectWithValue }) => {
  const mail = email.trim().toLowerCase();
  const existing = await authApi.findByEmail(mail);
  if (existing.length > 0) return rejectWithValue('Email is already registered');
  // vai trò do HỆ THỐNG đặt (student) — không bao giờ lấy từ form
  const user = await authApi.create({ fullName: fullName.trim(), email: mail, password, role: 'student', active: true, createdAt: todayISO() });
  return withoutPassword(user);
});

const initialState = { user: loadUser(), status: 'idle', error: null };

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    logout(state) {
      state.user = null;
      state.status = 'idle';
      state.error = null;
    },
    clearAuthError(state) {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    const pending = (state) => {
      state.status = 'loading';
      state.error = null;
    };
    const fulfilled = (state, action) => {
      state.status = 'succeeded';
      state.user = action.payload;
    };
    const rejected = (state, action) => {
      state.status = 'failed';
      // payload = thông điệp từ rejectWithValue; không có ⇒ lỗi mạng / json-server chưa chạy
      state.error = action.payload ?? 'Cannot reach the server. Is json-server running on port 9999?';
    };
    builder
      .addCase(login.pending, pending)
      .addCase(login.fulfilled, fulfilled)
      .addCase(login.rejected, rejected)
      .addCase(register.pending, pending)
      .addCase(register.fulfilled, fulfilled)
      .addCase(register.rejected, rejected);
  },
});

export const { logout, clearAuthError } = authSlice.actions;

export const selectUser = (state) => state.auth.user;
export const selectIsAdmin = (state) => state.auth.user?.role === 'admin';

export default authSlice.reducer;

// src/features/courses/coursesSlice.js — danh mục khoá học (catalog)
//   + chi tiết một khoá (detail)
//   + khu quản trị (admin: mọi khoá, kể cả bản nháp)
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import courseApi from '../../api/courseApi';
import enrollApi from '../../api/enrollApi';
import quizApi from '../../api/quizApi';

// Danh sách công khai + danh mục: tải SONG SONG (Promise.all), một trạng thái tải chung
export const fetchCatalog = createAsyncThunk('courses/fetchCatalog', async () => {
  const [courses, categories] = await Promise.all([courseApi.getPublishedCourses(), courseApi.getCategories()]);
  return { courses, categories };
});

const byOrder = (a, b) => a.order - b.order;

export const fetchCourseDetail = createAsyncThunk('courses/fetchDetail', async (id, { getState, rejectWithValue }) => {
  try {
    const [course, chapters, categories] = await Promise.all([
      courseApi.getCourse(id),
      courseApi.getCurriculum(id),
      courseApi.getCategories(),
    ]);
    // bản nháp: chỉ admin xem được — người khác coi như không tồn tại
    if (!course.published && getState().auth.user?.role !== 'admin') return rejectWithValue('notFound');
    return {
      course,
      categoryName: categories.find((c) => c.id === course.categoryId)?.name ?? 'Uncategorized',
      // _embed KHÔNG sắp bài học bên trong ⇒ tự sắp theo order (trên bản sao)
      chapters: chapters.slice().sort(byOrder).map((ch) => ({ ...ch, lessons: (ch.lessons ?? []).slice().sort(byOrder) })),
    };
  } catch (err) {
    if (err.response?.status === 404) return rejectWithValue('notFound');
    throw err;
  }
});

// ── admin ──
export const fetchAdminCourses = createAsyncThunk('courses/fetchAdmin', async () => {
  const [courses, categories, enrollments] = await Promise.all([courseApi.getAllCourses(), courseApi.getCategories(), enrollApi.getAll()]);
  const students = {};
  enrollments.forEach((e) => {
    students[e.courseId] = (students[e.courseId] ?? 0) + 1;
  });
  return { courses, categories, students };
});

export const createCourse = createAsyncThunk('courses/create', (course) => courseApi.createCourse(course));

export const updateCourse = createAsyncThunk('courses/update', ({ id, ...changes }) => courseApi.updateCourse(id, changes));

// Luật nghiệp vụ: khoá ĐÃ có học viên thì không xoá (mất tiến độ của họ) — chỉ được ẩn (Draft).
export const deleteCourse = createAsyncThunk('courses/delete', async (course, { rejectWithValue }) => {
  const enrolled = (await enrollApi.getByCourse(course.id)).length;
  if (enrolled > 0) {
    return rejectWithValue(`Cannot delete "${course.title}": ${enrolled} ${enrolled === 1 ? 'student is' : 'students are'} enrolled. Unpublish it instead.`);
  }
  // xoá con trước, khoá sau (json-server 0.17 tự dọn bản ghi con, nhưng đừng dựa vào điều đó)
  const [chapters, lessons, questions] = await Promise.all([
    courseApi.getByCourse('chapters', course.id),
    courseApi.getByCourse('lessons', course.id),
    quizApi.getByCourse(course.id),
  ]);
  await courseApi.deleteMany('lessons', lessons.map((l) => l.id));
  await courseApi.deleteMany('questions', questions.map((q) => q.id));
  await courseApi.deleteMany('chapters', chapters.map((c) => c.id));
  await courseApi.deleteCourse(course.id);
  return course.id;
});

const initialState = {
  items: [],          // khoá đã xuất bản (trang /courses)
  categories: [],
  status: 'idle',     // idle | loading | succeeded | failed
  error: null,
  detail: { course: null, categoryName: '', chapters: [], status: 'idle', error: null },
  admin: { items: [], students: {}, status: 'idle', error: null },
};

const coursesSlice = createSlice({
  name: 'courses',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchCatalog.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchCatalog.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.items = action.payload.courses;
        state.categories = action.payload.categories;
      })
      .addCase(fetchCatalog.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      })
      .addCase(fetchCourseDetail.pending, (state) => {
        // xoá khoá cũ ⇒ không "nháy" khoá trước trong lúc tải khoá mới
        state.detail = { ...initialState.detail, status: 'loading' };
      })
      .addCase(fetchCourseDetail.fulfilled, (state, action) => {
        state.detail = { ...action.payload, status: 'succeeded', error: null };
      })
      .addCase(fetchCourseDetail.rejected, (state, action) => {
        state.detail.status = 'failed';
        state.detail.error = action.payload ?? action.error.message;
      })
      .addCase(fetchAdminCourses.pending, (state) => {
        state.admin.status = 'loading';
        state.admin.error = null;
      })
      .addCase(fetchAdminCourses.fulfilled, (state, action) => {
        state.admin.status = 'succeeded';
        state.admin.items = action.payload.courses;
        state.admin.students = action.payload.students;
        state.categories = action.payload.categories;
      })
      .addCase(fetchAdminCourses.rejected, (state, action) => {
        state.admin.status = 'failed';
        state.admin.error = action.error.message;
      })
      .addCase(createCourse.fulfilled, (state, action) => {
        state.admin.items.push(action.payload);
        state.status = 'idle';   // danh mục công khai đã cũ ⇒ /courses tải lại lần tới
      })
      .addCase(updateCourse.fulfilled, (state, action) => {
        const i = state.admin.items.findIndex((c) => c.id === action.payload.id);
        if (i >= 0) state.admin.items[i] = action.payload;
        state.status = 'idle';
      })
      .addCase(deleteCourse.fulfilled, (state, action) => {
        state.admin.items = state.admin.items.filter((c) => c.id !== action.payload);
        state.status = 'idle';
      })
      ;
  },
});

export default coursesSlice.reducer;

// src/features/enrollments/enrollmentsSlice.js — các khoá học viên đã đăng ký
//   + tiến độ (completedLessons) và tổng bài của từng khoá
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import enrollApi from '../../api/enrollApi';
import courseApi from '../../api/courseApi';
import { logout } from '../auth/authSlice';
import { todayISO } from '../../utils/format';

export const fetchMyEnrollments = createAsyncThunk('enrollments/fetchMine', async (userId) => {
  const items = await enrollApi.getByUser(userId);
  // tổng số bài của từng khoá (để tính %) — MỘT lần gọi cho mọi khoá
  const lessons = items.length ? await courseApi.getLessonsOfCourses(items.map((e) => e.courseId)) : [];
  const totals = {};
  lessons.forEach((l) => {
    totals[l.courseId] = (totals[l.courseId] ?? 0) + 1;
  });
  return { items, totals };
});

export const enrollCourse = createAsyncThunk(
  'enrollments/enroll',
  async ({ userId, courseId }) => {
    // hỏi lại máy chủ trước khi ghi: không tạo bản ghi trùng (hai tab, hay state cũ)
    const existing = await enrollApi.find(userId, courseId);
    if (existing.length > 0) return existing[0];
    return enrollApi.create({ userId, courseId, enrolledAt: todayISO(), completedLessons: [] });
  },
  // đang gửi ⇒ bỏ qua cú bấm thứ hai (double click) — thunk không chạy, không có POST thứ hai
  { condition: (_, { getState }) => getState().enrollments.enrollStatus !== 'loading' },
);

// Đánh dấu / bỏ đánh dấu một bài: tạo MẢNG MỚI (không push vào mảng của state), bỏ trùng, sắp tăng dần
export const toggleLessonComplete = createAsyncThunk('enrollments/toggleLesson', async ({ enrollment, lessonId }) => {
  const done = new Set(enrollment.completedLessons);
  if (done.has(lessonId)) done.delete(lessonId);
  else done.add(lessonId);
  return enrollApi.updateProgress(enrollment.id, [...done].sort((a, b) => a - b));
});

const initialState = {
  items: [],
  totals: {},          // { courseId: số bài }
  status: 'idle',
  error: null,
  enrollStatus: 'idle',
  savingLesson: false,
};

const enrollmentsSlice = createSlice({
  name: 'enrollments',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchMyEnrollments.pending, (state) => {
        state.status = 'loading';
        state.error = null;
      })
      .addCase(fetchMyEnrollments.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.items = action.payload.items;
        state.totals = action.payload.totals;
      })
      .addCase(fetchMyEnrollments.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message;
      })
      .addCase(enrollCourse.pending, (state) => {
        state.enrollStatus = 'loading';
      })
      .addCase(enrollCourse.fulfilled, (state, action) => {
        state.enrollStatus = 'succeeded';
        if (!state.items.some((e) => e.id === action.payload.id)) state.items.unshift(action.payload);
      })
      .addCase(enrollCourse.rejected, (state, action) => {
        // condition false cũng sinh action rejected (meta.condition) — không được đè trạng thái của lượt đang chạy
        if (!action.meta.condition) state.enrollStatus = 'failed';
      })
      .addCase(toggleLessonComplete.pending, (state) => {
        state.savingLesson = true;
      })
      .addCase(toggleLessonComplete.fulfilled, (state, action) => {
        state.savingLesson = false;
        const e = state.items.find((x) => x.id === action.payload.id);
        if (e) e.completedLessons = action.payload.completedLessons;   // giữ e.course đã _expand
      })
      .addCase(toggleLessonComplete.rejected, (state) => {
        state.savingLesson = false;
      })
      // đăng xuất ⇒ quên dữ liệu của người cũ (đăng nhập tài khoản khác không thấy khoá của người trước)
      .addCase(logout, () => initialState);
  },
});

export const selectEnrollmentByCourse = (state, courseId) => state.enrollments.items.find((e) => e.courseId === courseId);

export default enrollmentsSlice.reducer;

// src/features/quiz/quizSlice.js — làm quiz cuối chương: tải câu hỏi, giữ câu trả lời, chấm + lưu kết quả
//   + lịch sử làm bài của học viên (trang My Progress)
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import quizApi from '../../api/quizApi';
import { logout } from '../auth/authSlice';
import { scoreQuiz } from '../../utils/learning';

export const fetchQuiz = createAsyncThunk('quiz/fetch', async (chapterId, { rejectWithValue }) => {
  try {
    const [chapter, questions] = await Promise.all([quizApi.getChapter(chapterId), quizApi.getQuestions(chapterId)]);
    return { chapter, questions };
  } catch (err) {
    if (err.response?.status === 404) return rejectWithValue('notFound');
    throw err;
  }
});

// chấm ở client (json-server không chấm được), rồi LƯU kết quả — chỉ hiện điểm khi đã lưu xong
export const submitQuiz = createAsyncThunk('quiz/submit', async ({ userId }, { getState }) => {
  const { chapter, questions, answers } = getState().quiz;
  const { score, total, percent, passed } = scoreQuiz(questions, answers);
  return quizApi.saveResult({
    userId,
    courseId: chapter.courseId,
    chapterId: chapter.id,
    score,
    total,
    percent,
    passed,
    answers: questions.map((q) => answers[q.id]),
    submittedAt: new Date().toISOString(),
  });
});

export const fetchMyResults = createAsyncThunk('quiz/fetchMyResults', (userId) => quizApi.getResultsByUser(userId));

const initialState = {
  chapter: null,
  questions: [],
  answers: {},          // { [questionId]: optionIndex }
  result: null,         // bản ghi results vừa lưu
  status: 'idle',
  error: null,
  submitStatus: 'idle',
  history: [],
  historyStatus: 'idle',
};

const quizSlice = createSlice({
  name: 'quiz',
  initialState,
  reducers: {
    answerSelected(state, action) {
      if (state.result) return;                    // đã nộp ⇒ khoá câu trả lời
      const { questionId, optionIndex } = action.payload;
      state.answers[questionId] = optionIndex;
    },
    retakeQuiz(state) {
      state.answers = {};
      state.result = null;
      state.submitStatus = 'idle';
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchQuiz.pending, (state) => {
        // làm bài mới ⇒ bỏ câu trả lời / điểm của chương trước
        Object.assign(state, { chapter: null, questions: [], answers: {}, result: null, status: 'loading', error: null, submitStatus: 'idle' });
      })
      .addCase(fetchQuiz.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.chapter = action.payload.chapter;
        state.questions = action.payload.questions;
      })
      .addCase(fetchQuiz.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.payload ?? action.error.message;
      })
      .addCase(submitQuiz.pending, (state) => {
        state.submitStatus = 'loading';
      })
      .addCase(submitQuiz.fulfilled, (state, action) => {
        state.submitStatus = 'succeeded';
        state.result = action.payload;
      })
      .addCase(submitQuiz.rejected, (state) => {
        state.submitStatus = 'failed';
      })
      .addCase(fetchMyResults.pending, (state) => {
        state.historyStatus = 'loading';
      })
      .addCase(fetchMyResults.fulfilled, (state, action) => {
        state.historyStatus = 'succeeded';
        state.history = action.payload;
      })
      .addCase(fetchMyResults.rejected, (state) => {
        state.historyStatus = 'failed';
      })
      .addCase(logout, () => initialState);
  },
});

export const { answerSelected, retakeQuiz } = quizSlice.actions;
export default quizSlice.reducer;

/* src/index.css — CodeLearn (đã cho sẵn; sửa thoải mái) */
