// src/pages/ProgressPage.js — bảng tiến độ của học viên: 5 con số tổng + tiến độ từng khoá + lịch sử quiz
import { useEffect } from 'react';
import { Alert, Badge, Card, Col, ProgressBar, Row, Spinner, Table } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import { selectUser } from '../features/auth/authSlice';
import { fetchMyEnrollments } from '../features/enrollments/enrollmentsSlice';
import { fetchMyResults } from '../features/quiz/quizSlice';
import { formatDate } from '../utils/format';
import { calcProgress } from '../utils/learning';

function StatCard({ id, label, value }) {
  return (
    <Col>
      <Card className="h-100 shadow-sm text-center">
        <Card.Body>
          <div id={id} className="fs-3 fw-bold">{value}</div>
          <div className="small text-muted">{label}</div>
        </Card.Body>
      </Card>
    </Col>
  );
}

export default function ProgressPage() {
  const dispatch = useDispatch();
  const user = useSelector(selectUser);
  const { items, totals, status } = useSelector((state) => state.enrollments);
  const { history, historyStatus } = useSelector((state) => state.quiz);

  useEffect(() => {
    dispatch(fetchMyEnrollments(user.id));
    dispatch(fetchMyResults(user.id));
  }, [user.id, dispatch]);

  if (status !== 'succeeded' || historyStatus !== 'succeeded') {
    if (status === 'failed' || historyStatus === 'failed') return <Alert variant="danger" id="progress-error">Could not load your progress.</Alert>;
    return <div id="progress-loading" className="text-center py-5"><Spinner animation="border" /></div>;
  }

  // mọi con số đều SUY RA từ dữ liệu máy chủ — không lưu "đã xong bao nhiêu" ở đâu khác
  const rows = items.map((e) => {
    const total = totals[e.courseId] ?? 0;
    const done = Math.min(e.completedLessons.length, total);
    const attempts = history.filter((r) => r.courseId === e.courseId);
    return {
      id: e.id,
      title: e.course?.title ?? 'Course no longer available',
      done,
      total,
      pct: calcProgress(done, total),
      best: attempts.length ? Math.max(...attempts.map((r) => r.percent)) : null,
    };
  });
  const passedChapters = new Set(history.filter((r) => r.passed).map((r) => r.chapterId)).size;
  const avg = history.length ? `${Math.round(history.reduce((s, r) => s + r.percent, 0) / history.length)}%` : '—';

  return (
    <>
      <h2 id="progress-title">My Progress</h2>
      <Row xs={2} md={5} className="g-3 mb-4">
        <StatCard id="stat-enrolled" label="Courses enrolled" value={items.length} />
        <StatCard id="stat-completed" label="Courses completed" value={rows.filter((r) => r.total > 0 && r.pct === 100).length} />
        <StatCard id="stat-lessons" label="Lessons completed" value={rows.reduce((s, r) => s + r.done, 0)} />
        <StatCard id="stat-quizzes" label="Quizzes passed" value={passedChapters} />
        <StatCard id="stat-avg" label="Average quiz score" value={avg} />
      </Row>

      <h4>Courses</h4>
      {rows.length === 0 ? (
        <Alert variant="info" id="no-progress">Start a course to see your progress here. <Link to="/courses">Browse courses</Link></Alert>
      ) : (
        <Table responsive hover className="bg-white shadow-sm align-middle" id="progress-table">
          <thead>
            <tr><th>Course</th><th>Lessons</th><th style={{ minWidth: 160 }}>Progress</th><th>Best quiz</th></tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id} className="progress-row">
                <td className="progress-course">{r.title}</td>
                <td className="progress-lessons">{r.done}/{r.total}</td>
                <td className="progress-percent"><ProgressBar now={r.pct} label={`${r.pct}%`} variant={r.pct === 100 ? 'success' : 'primary'} /></td>
                <td className="progress-best">{r.best === null ? '—' : `${r.best}%`}</td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}

      <h4 className="mt-4">Quiz history</h4>
      {history.length === 0 ? (
        <Alert variant="secondary" id="no-quiz-history">No quiz attempts yet.</Alert>
      ) : (
        <Table responsive className="bg-white shadow-sm align-middle" id="quiz-history">
          <thead>
            <tr><th>Chapter</th><th>Date</th><th>Score</th><th>Result</th></tr>
          </thead>
          <tbody>
            {history.map((r) => (
              <tr key={r.id} className="quiz-row">
                <td className="quiz-chapter">{r.chapter?.title ?? `Chapter #${r.chapterId}`}</td>
                <td className="quiz-date">{formatDate(r.submittedAt)}</td>
                <td className="quiz-score">{r.score}/{r.total} ({r.percent}%)</td>
                <td className="quiz-status"><Badge bg={r.passed ? 'success' : 'danger'}>{r.passed ? 'Passed' : 'Failed'}</Badge></td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </>
  );
}

// src/pages/QuizPage.js — quiz cuối chương: chọn đáp án, nộp (phải trả lời hết), xem điểm + xem lại từng câu
import { useEffect, useState } from 'react';
import { Alert, Button, Card, Form, Spinner } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { Link, useParams } from 'react-router-dom';
import { selectUser } from '../features/auth/authSlice';
import { fetchMyEnrollments } from '../features/enrollments/enrollmentsSlice';
import { answerSelected, fetchQuiz, retakeQuiz, submitQuiz } from '../features/quiz/quizSlice';
import { PASS_PERCENT } from '../utils/learning';

export default function QuizPage() {
  const { chapterId } = useParams();
  const dispatch = useDispatch();
  const user = useSelector(selectUser);
  const { chapter, questions, answers, result, status, error, submitStatus } = useSelector((state) => state.quiz);
  const enrollments = useSelector((state) => state.enrollments);
  const [formError, setFormError] = useState('');

  useEffect(() => {
    dispatch(fetchQuiz(chapterId));
  }, [chapterId, dispatch]);
  useEffect(() => {
    dispatch(fetchMyEnrollments(user.id));
  }, [user.id, dispatch]);

  if (status === 'failed') {
    return <Alert variant="danger" id="quiz-not-found">{error === 'notFound' ? 'Chapter not found.' : `Could not load the quiz (${error}).`}</Alert>;
  }
  if (status !== 'succeeded' || enrollments.status !== 'succeeded') {
    return <div id="quiz-loading" className="text-center py-5"><Spinner animation="border" /></div>;
  }
  // chỉ học viên đã đăng ký khoá chứa chương này mới được làm (mở thẳng URL cũng bị chặn)
  if (!enrollments.items.some((e) => e.courseId === chapter.courseId)) {
    return (
      <Alert variant="warning" id="not-enrolled">
        You are not enrolled in this course. <Link to={`/courses/${chapter.courseId}`}>View the course</Link>
      </Alert>
    );
  }

  const handleSubmit = (e) => {
    e.preventDefault();
    const missing = questions.filter((q) => answers[q.id] === undefined).length;
    if (missing > 0) {
      setFormError(`Please answer all questions (${missing} unanswered).`);
      return;
    }
    setFormError('');
    dispatch(submitQuiz({ userId: user.id }));
  };

  const handleRetake = () => {
    setFormError('');
    dispatch(retakeQuiz());
  };

  return (
    <>
      <Link to={`/learn/${chapter.courseId}`} id="back-to-learn" className="small">← Back to lessons</Link>
      <h2 id="quiz-title" className="mt-2">Quiz: {chapter.title}</h2>
      <p className="text-muted">{questions.length} questions · pass mark {PASS_PERCENT}%</p>

      {questions.length === 0 ? (
        <Alert variant="secondary" id="no-questions">This chapter has no quiz questions yet.</Alert>
      ) : (
        <Form id="quiz-form" noValidate onSubmit={handleSubmit}>
          {result && (
            <Alert variant={result.passed ? 'success' : 'warning'} id="quiz-result">
              You scored {result.score}/{result.total} ({result.percent}%) — {result.passed ? 'Passed 🎉' : 'Not passed'}
            </Alert>
          )}
          {questions.map((q, i) => {
            const chosen = answers[q.id];
            const verdict = result ? (chosen === q.answerIndex ? ' correct' : ' incorrect') : '';
            return (
              <Card key={q.id} className={`question mb-3${verdict}`} id={`q-${q.id}`}>
                <Card.Body>
                  <Card.Title className="question-text fs-6">{i + 1}. {q.content}</Card.Title>
                  {q.options.map((option, oi) => {
                    // sau khi nộp: tô xanh đáp án đúng, gạch đỏ đáp án sai đã chọn
                    let cls = 'option';
                    if (result && oi === q.answerIndex) cls += ' option-correct';
                    else if (result && oi === chosen) cls += ' option-wrong';
                    return (
                      <Form.Check
                        key={oi}
                        type="radio"
                        id={`q${q.id}-o${oi}`}
                        name={`q-${q.id}`}
                        label={option}
                        className={cls}
                        checked={chosen === oi}
                        disabled={!!result}
                        onChange={() => dispatch(answerSelected({ questionId: q.id, optionIndex: oi }))}
                      />
                    );
                  })}
                  {result && q.explanation && <div className="explanation small text-muted mt-2">💡 {q.explanation}</div>}
                </Card.Body>
              </Card>
            );
          })}
          {formError && <Alert variant="danger" id="quiz-error">{formError}</Alert>}
          {submitStatus === 'failed' && <Alert variant="danger" id="quiz-save-error">Your answers could not be saved. Please try again.</Alert>}
          {result ? (
            <Button id="retake-quiz" variant="outline-primary" onClick={handleRetake}>Retake quiz</Button>
          ) : (
            <Button id="submit-quiz" type="submit" disabled={submitStatus === 'loading'}>Submit answers</Button>
          )}
        </Form>
      )}
    </>
  );
}

// src/pages/RegisterPage.js — đăng ký học viên mới: 4 luật kiểm + chặn email trùng (hỏi máy chủ)
import { useEffect, useState } from 'react';
import { Alert, Button, Card, Form, Spinner } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { Link, Navigate } from 'react-router-dom';
import { clearAuthError, register, selectUser } from '../features/auth/authSlice';
import { validateRegister } from '../utils/validators';

const EMPTY = { fullName: '', email: '', password: '', confirmPassword: '' };
const FIELDS = [
  ['fullName', 'Full name', 'text'],
  ['email', 'Email', 'email'],
  ['password', 'Password', 'password'],
  ['confirmPassword', 'Confirm password', 'password'],
];

export default function RegisterPage() {
  const dispatch = useDispatch();
  const user = useSelector(selectUser);
  const { status, error } = useSelector((state) => state.auth);
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    dispatch(clearAuthError());
  }, [dispatch]);

  // Đăng ký thành công = đã đăng nhập (thunk trả user) ⇒ về trang chủ
  if (user) return <Navigate to="/" replace />;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((f) => ({ ...f, [name]: value }));
    setErrors((er) => ({ ...er, [name]: undefined }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const found = validateRegister(form);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    dispatch(register(form));    // email trùng ⇒ thunk rejectWithValue ⇒ #register-error
  };

  return (
    <Card className="mx-auto shadow-sm" style={{ maxWidth: 460 }}>
      <Card.Body className="p-4">
        <h2 className="mb-3">Create your account</h2>
        {error && <Alert variant="danger" id="register-error">{error}</Alert>}
        <Form id="register-form" noValidate onSubmit={handleSubmit}>
          {FIELDS.map(([name, label, type]) => (
            <Form.Group className="mb-3" controlId={name} key={name}>
              <Form.Label>{label}</Form.Label>
              <Form.Control type={type} name={name} value={form[name]} onChange={handleChange} isInvalid={!!errors[name]} />
              <Form.Control.Feedback type="invalid" id={`${name}-error`}>{errors[name]}</Form.Control.Feedback>
            </Form.Group>
          ))}
          <Button type="submit" id="register-btn" className="w-100" disabled={status === 'loading'}>
            {status === 'loading' ? <Spinner size="sm" animation="border" /> : 'Register'}
          </Button>
        </Form>
        <p className="mt-3 mb-0 small text-center">
          Already have an account? <Link to="/login" id="to-login">Log in</Link>
        </p>
      </Card.Body>
    </Card>
  );
}

// src/pages/admin/AdminCoursesPage.js — quản lý khoá học: bảng mọi khoá (cả bản nháp), thêm / sửa / xoá
import { useEffect, useState } from 'react';
import { Alert, Badge, Button, Spinner, Table } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { Link, useLocation } from 'react-router-dom';
import { deleteCourse, fetchAdminCourses } from '../../features/courses/coursesSlice';
import { formatPrice } from '../../utils/format';

export default function AdminCoursesPage() {
  const dispatch = useDispatch();
  const location = useLocation();
  const { items, students, status, error } = useSelector((state) => state.courses.admin);
  const categories = useSelector((state) => state.courses.categories);
  // thông báo "đã lưu" gửi sang từ trang form qua location.state
  const [success, setSuccess] = useState(location.state?.flash ?? '');
  const [actionError, setActionError] = useState('');

  useEffect(() => {
    dispatch(fetchAdminCourses());
  }, [dispatch]);

  const handleDelete = async (course) => {
    setSuccess('');
    setActionError('');
    if (!window.confirm(`Delete "${course.title}"? This cannot be undone.`)) return;
    try {
      await dispatch(deleteCourse(course)).unwrap();
      setSuccess(`Course "${course.title}" was deleted.`);
    } catch (err) {
      setActionError(typeof err === 'string' ? err : 'Could not delete the course.');
    }
  };

  const categoryName = (id) => categories.find((c) => c.id === id)?.name ?? '—';
  const sorted = items.slice().sort((a, b) => a.id - b.id);

  return (
    <>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <h2 id="admin-courses-title" className="mb-0">Courses</h2>
        <Link to="/admin/courses/new" id="add-course" className="btn btn-primary">+ Add course</Link>
      </div>
      {success && <Alert variant="success" id="admin-success" dismissible onClose={() => setSuccess('')}>{success}</Alert>}
      {actionError && <Alert variant="danger" id="admin-error" dismissible onClose={() => setActionError('')}>{actionError}</Alert>}
      {status === 'loading' && items.length === 0 && <div className="text-center py-5"><Spinner animation="border" /></div>}
      {status === 'failed' && <Alert variant="danger" id="admin-load-error">Could not load courses ({error}).</Alert>}
      {items.length > 0 && (
        <Table responsive hover className="bg-white shadow-sm align-middle" id="admin-courses-table">
          <thead>
            <tr><th>#</th><th>Title</th><th>Category</th><th>Level</th><th>Price</th><th>Students</th><th>Status</th><th className="text-end">Actions</th></tr>
          </thead>
          <tbody>
            {sorted.map((c) => (
              <tr key={c.id} className="admin-course-row" id={`admin-course-${c.id}`}>
                <td>{c.id}</td>
                <td className="admin-course-title">{c.title}</td>
                <td>{categoryName(c.categoryId)}</td>
                <td>{c.level}</td>
                <td className="admin-course-price">{formatPrice(c.price)}</td>
                <td className="admin-course-students">{students[c.id] ?? 0}</td>
                <td><Badge bg={c.published ? 'success' : 'secondary'} className="badge-status">{c.published ? 'Published' : 'Draft'}</Badge></td>
                <td className="text-end text-nowrap">
                  <Link to={`/admin/courses/${c.id}/edit`} className="btn btn-sm btn-outline-primary btn-edit me-1">Edit</Link>
                  <Link to={`/admin/courses/${c.id}/curriculum`} className="btn btn-sm btn-outline-secondary btn-curriculum me-1">Curriculum</Link>
                  <Button size="sm" variant="outline-danger" className="btn-delete" onClick={() => handleDelete(c)}>Delete</Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </>
  );
}

// src/pages/admin/AdminQuestionsPage.js — ngân hàng câu hỏi quiz: chọn khoá ▸ chương, thêm / sửa / xoá câu hỏi
import { useCallback, useEffect, useState } from 'react';
import { Alert, Button, Card, Col, Form, Row, Table } from 'react-bootstrap';
import courseApi from '../../api/courseApi';
import quizApi from '../../api/quizApi';
import { validateQuestion } from '../../utils/validators';

const LETTERS = ['A', 'B', 'C', 'D'];
const EMPTY = { content: '', options: ['', '', '', ''], answer: '', explanation: '' };

export default function AdminQuestionsPage() {
  const [courses, setCourses] = useState([]);
  const [chapters, setChapters] = useState([]);
  const [courseId, setCourseId] = useState('');
  const [chapterId, setChapterId] = useState('');
  const [questions, setQuestions] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});
  const [editingId, setEditingId] = useState(null);
  const [message, setMessage] = useState('');
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    courseApi.getAllCourses().then(setCourses).catch(() => setLoadError('Could not load courses.'));
  }, []);

  // đổi khoá ⇒ tải chương của khoá đó, bỏ chương đang chọn
  useEffect(() => {
    setChapterId('');
    setChapters([]);
    if (courseId) courseApi.getCurriculum(courseId).then(setChapters).catch(() => setLoadError('Could not load chapters.'));
  }, [courseId]);

  const loadQuestions = useCallback(
    (chId) => quizApi.getQuestions(chId).then(setQuestions).catch(() => setLoadError('Could not load questions.')),
    [],
  );

  useEffect(() => {
    setQuestions([]);
    setEditingId(null);
    setForm(EMPTY);
    if (chapterId) loadQuestions(chapterId);
  }, [chapterId, loadQuestions]);

  const setOption = (i, value) => {
    setForm((f) => ({ ...f, options: f.options.map((o, j) => (j === i ? value : o)) }));   // mảng MỚI, không sửa tại chỗ
    setErrors((er) => ({ ...er, options: undefined }));
  };

  const startEdit = (q) => {
    setEditingId(q.id);
    setForm({ content: q.content, options: [...q.options], answer: String(q.answerIndex), explanation: q.explanation ?? '' });
    setErrors({});
  };

  const cancelEdit = () => {
    setEditingId(null);
    setForm(EMPTY);
    setErrors({});
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const found = validateQuestion(form);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    const question = {
      chapterId: Number(chapterId),
      courseId: Number(courseId),
      content: form.content.trim(),
      options: form.options.map((o) => o.trim()),
      answerIndex: Number(form.answer),           // SỐ — so === với lựa chọn của học viên
      explanation: form.explanation.trim(),
    };
    try {
      if (editingId) await quizApi.updateQuestion(editingId, question);
      else await quizApi.createQuestion(question);
      setMessage(editingId ? 'Question updated.' : 'Question added.');
      cancelEdit();
      loadQuestions(chapterId);
    } catch {
      setLoadError('Could not save the question.');
    }
  };

  const handleDelete = async (q) => {
    if (!window.confirm('Delete this question?')) return;
    await quizApi.deleteQuestion(q.id);
    setMessage('Question deleted.');
    loadQuestions(chapterId);
  };

  return (
    <>
      <h2 id="admin-questions-title" className="h4">Quiz questions</h2>
      {loadError && <Alert variant="danger" id="questions-error">{loadError}</Alert>}
      {message && <Alert variant="success" id="question-success" dismissible onClose={() => setMessage('')}>{message}</Alert>}
      <Row className="g-2 mb-3">
        <Col md={6}>
          <Form.Select id="q-course" value={courseId} onChange={(e) => setCourseId(e.target.value)}>
            <option value="">— Choose a course —</option>
            {courses.map((c) => <option key={c.id} value={c.id}>{c.title}</option>)}
          </Form.Select>
        </Col>
        <Col md={6}>
          <Form.Select id="q-chapter" value={chapterId} onChange={(e) => setChapterId(e.target.value)} disabled={!courseId}>
            <option value="">— Choose a chapter —</option>
            {chapters.map((c, i) => <option key={c.id} value={c.id}>Chapter {i + 1}: {c.title}</option>)}
          </Form.Select>
        </Col>
      </Row>

      {!chapterId ? (
        <Alert variant="secondary" id="choose-chapter">Choose a course and a chapter to manage its questions.</Alert>
      ) : (
        <Row className="g-4">
          <Col lg={7}>
            {questions.length === 0 ? (
              <Alert variant="secondary" id="no-questions-admin">This chapter has no questions yet.</Alert>
            ) : (
              <Table responsive className="bg-white shadow-sm align-middle" id="questions-table">
                <thead><tr><th>#</th><th>Question</th><th>Correct answer</th><th /></tr></thead>
                <tbody>
                  {questions.map((q, i) => (
                    <tr key={q.id} className="admin-question-row" id={`admin-question-${q.id}`}>
                      <td>{i + 1}</td>
                      <td className="admin-question-content">{q.content}</td>
                      <td className="admin-question-answer">{LETTERS[q.answerIndex]}. {q.options[q.answerIndex]}</td>
                      <td className="text-nowrap text-end">
                        <Button size="sm" variant="outline-primary" className="btn-edit-question me-1" onClick={() => startEdit(q)}>Edit</Button>
                        <Button size="sm" variant="outline-danger" className="btn-delete-question" onClick={() => handleDelete(q)}>Delete</Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            )}
          </Col>
          <Col lg={5}>
            <Card className="shadow-sm">
              <Card.Body>
                <h5 id="question-form-title">{editingId ? 'Edit question' : 'Add a question'}</h5>
                <Form id="question-form" noValidate onSubmit={handleSubmit}>
                  <Form.Group className="mb-2" controlId="q-content">
                    <Form.Label>Question</Form.Label>
                    <Form.Control as="textarea" rows={2} value={form.content} isInvalid={!!errors.content}
                      onChange={(e) => { setForm((f) => ({ ...f, content: e.target.value })); setErrors((er) => ({ ...er, content: undefined })); }} />
                    <Form.Control.Feedback type="invalid" id="q-content-error">{errors.content}</Form.Control.Feedback>
                  </Form.Group>
                  {form.options.map((o, i) => (
                    <Form.Control key={i} id={`q-option-${i}`} className="mb-2" placeholder={`Option ${LETTERS[i]}`} value={o} isInvalid={!!errors.options} onChange={(e) => setOption(i, e.target.value)} />
                  ))}
                  <div id="q-options-error" className="text-danger small mb-2">{errors.options}</div>
                  <Form.Group className="mb-2" controlId="q-answer">
                    <Form.Label>Correct answer</Form.Label>
                    <Form.Select value={form.answer} isInvalid={!!errors.answer}
                      onChange={(e) => { setForm((f) => ({ ...f, answer: e.target.value })); setErrors((er) => ({ ...er, answer: undefined })); }}>
                      <option value="">— Choose —</option>
                      {LETTERS.map((l, i) => <option key={l} value={i}>Option {l}</option>)}
                    </Form.Select>
                    <Form.Control.Feedback type="invalid" id="q-answer-error">{errors.answer}</Form.Control.Feedback>
                  </Form.Group>
                  <Form.Group className="mb-3" controlId="q-explanation">
                    <Form.Label>Explanation (optional)</Form.Label>
                    <Form.Control value={form.explanation} onChange={(e) => setForm((f) => ({ ...f, explanation: e.target.value }))} />
                  </Form.Group>
                  <div className="d-flex gap-2">
                    <Button type="submit" id="save-question">{editingId ? 'Update question' : 'Add question'}</Button>
                    {editingId && <Button variant="outline-secondary" id="cancel-question" onClick={cancelEdit}>Cancel</Button>}
                  </div>
                </Form>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </>
  );
}

// src/pages/admin/AdminUsersPage.js — quản lý người dùng: tìm, khoá/mở khoá, đổi vai trò, xoá (không tự hại mình)
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, Badge, Button, Form, Spinner, Table } from 'react-bootstrap';
import { useSelector } from 'react-redux';
import authApi from '../../api/authApi';
import enrollApi from '../../api/enrollApi';
import quizApi from '../../api/quizApi';
import { selectUser } from '../../features/auth/authSlice';

export default function AdminUsersPage() {
  const me = useSelector(selectUser);
  const [users, setUsers] = useState([]);
  const [enrollments, setEnrollments] = useState([]);
  const [status, setStatus] = useState('loading');
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    try {
      const [u, e] = await Promise.all([authApi.getAll(), enrollApi.getAll()]);
      setUsers(u);
      setEnrollments(e);
      setStatus('succeeded');
    } catch {
      setStatus('failed');
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const shown = useMemo(() => {
    const k = search.trim().toLowerCase();
    return users.filter((u) => !k || u.fullName.toLowerCase().includes(k) || u.email.toLowerCase().includes(k));
  }, [users, search]);

  // cập nhật MỘT dòng trong state bằng bản máy chủ trả về — không tải lại cả bảng
  const patch = async (user, changes, done) => {
    setError('');
    try {
      const saved = await authApi.update(user.id, changes);
      setUsers((list) => list.map((u) => (u.id === saved.id ? saved : u)));
      setMessage(done);
    } catch {
      setError('Could not update the user.');
    }
  };

  const remove = async (user) => {
    if (!window.confirm(`Delete ${user.fullName}? Their enrolments and quiz results are deleted too.`)) return;
    setError('');
    try {
      const results = await quizApi.getResultsByUser(user.id);
      await Promise.allSettled([
        ...enrollments.filter((e) => e.userId === user.id).map((e) => enrollApi.remove(e.id)),
        ...results.map((r) => quizApi.deleteResult(r.id)),
      ]);
      await authApi.remove(user.id);
      setMessage(`${user.fullName} was deleted.`);
      load();
    } catch {
      setError('Could not delete the user.');
    }
  };

  const enrolledCount = (userId) => enrollments.filter((e) => e.userId === userId).length;

  if (status === 'loading') return <div className="text-center py-5"><Spinner animation="border" /></div>;
  if (status === 'failed') return <Alert variant="danger" id="users-load-error">Could not load users.</Alert>;

  return (
    <>
      <h2 id="admin-users-title" className="h4">Users</h2>
      {message && <Alert variant="success" id="users-success" dismissible onClose={() => setMessage('')}>{message}</Alert>}
      {error && <Alert variant="danger" id="users-error">{error}</Alert>}
      <Form.Control id="user-search" type="search" placeholder="Search by name or email" className="mb-3" value={search} onChange={(e) => setSearch(e.target.value)} />
      <Table responsive hover className="bg-white shadow-sm align-middle" id="users-table">
        <thead>
          <tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Enrolled</th><th className="text-end">Actions</th></tr>
        </thead>
        <tbody>
          {shown.map((u) => {
            const isMe = u.id === me.id;   // admin không tự khoá / tự hạ quyền / tự xoá mình
            return (
              <tr key={u.id} className="admin-user-row" id={`admin-user-${u.id}`}>
                <td className="admin-user-name">{u.fullName}{isMe && <span className="text-muted small"> (you)</span>}</td>
                <td className="admin-user-email">{u.email}</td>
                <td><Badge bg={u.role === 'admin' ? 'dark' : 'info'} className="admin-user-role">{u.role}</Badge></td>
                <td><Badge bg={u.active === false ? 'danger' : 'success'} className="admin-user-status">{u.active === false ? 'Locked' : 'Active'}</Badge></td>
                <td className="admin-user-enrolled">{enrolledCount(u.id)}</td>
                <td className="text-end text-nowrap">
                  <Button size="sm" variant="outline-warning" className="btn-toggle-lock me-1" disabled={isMe}
                    onClick={() => patch(u, { active: u.active === false }, `${u.fullName} was ${u.active === false ? 'unlocked' : 'locked'}.`)}>
                    {u.active === false ? 'Unlock' : 'Lock'}
                  </Button>
                  <Button size="sm" variant="outline-secondary" className="btn-toggle-role me-1" disabled={isMe}
                    onClick={() => patch(u, { role: u.role === 'admin' ? 'student' : 'admin' }, `${u.fullName} is now ${u.role === 'admin' ? 'a student' : 'an admin'}.`)}>
                    {u.role === 'admin' ? 'Make student' : 'Make admin'}
                  </Button>
                  <Button size="sm" variant="outline-danger" className="btn-delete-user" disabled={isMe} onClick={() => remove(u)}>Delete</Button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </Table>
      {shown.length === 0 && <Alert variant="secondary" id="no-users">No users match “{search}”.</Alert>}
    </>
  );
}

// src/pages/admin/CourseFormPage.js — MỘT form cho cả thêm (/admin/courses/new) và sửa (/admin/courses/:id/edit)
import { useEffect, useState } from 'react';
import { Alert, Button, Card, Col, Form, Row, Spinner } from 'react-bootstrap';
import { useDispatch } from 'react-redux';
import { Link, useNavigate, useParams } from 'react-router-dom';
import courseApi from '../../api/courseApi';
import { createCourse, updateCourse } from '../../features/courses/coursesSlice';
import { LEVELS } from '../../utils/courseQuery';
import { todayISO } from '../../utils/format';
import { validateCourse } from '../../utils/validators';

const EMPTY = { title: '', categoryId: '', level: '', price: '', instructor: '', description: '', thumbnail: '', published: true };

export default function CourseFormPage() {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [form, setForm] = useState(EMPTY);
  const [errors, setErrors] = useState({});
  const [categories, setCategories] = useState([]);
  const [allCourses, setAllCourses] = useState([]);   // để kiểm trùng tên
  const [loading, setLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');

  useEffect(() => {
    let cancelled = false;   // rời trang trước khi API trả về ⇒ không setState trên component đã gỡ
    Promise.all([courseApi.getCategories(), courseApi.getAllCourses()])
      .then(([cats, courses]) => {
        if (cancelled) return;
        setCategories(cats);
        setAllCourses(courses);
        if (isEdit) {
          const course = courses.find((c) => c.id === Number(id));
          if (!course) setNotFound(true);
          // điền sẵn (prefill): ô <select>/<input> làm việc với CHUỖI ⇒ đổi số sang chuỗi
          else setForm({ ...EMPTY, ...course, categoryId: String(course.categoryId), price: String(course.price), thumbnail: course.thumbnail ?? '' });
        }
      })
      .catch(() => !cancelled && setSaveError('Could not load data from the server.'))
      .finally(() => !cancelled && setLoading(false));
    return () => {
      cancelled = true;
    };
  }, [id, isEdit]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm((f) => ({ ...f, [name]: type === 'checkbox' ? checked : value }));
    setErrors((er) => ({ ...er, [name]: undefined }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const found = validateCourse(form, allCourses, isEdit ? Number(id) : null);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    // gửi đúng KIỂU: categoryId/price là số (không phải "1", "259000")
    const payload = {
      title: form.title.trim(),
      categoryId: Number(form.categoryId),
      level: form.level,
      price: Number(form.price),
      instructor: form.instructor.trim(),
      description: form.description.trim(),
      thumbnail: form.thumbnail.trim(),
      published: form.published,
    };
    setSaving(true);
    setSaveError('');
    try {
      if (isEdit) await dispatch(updateCourse({ id: Number(id), ...payload })).unwrap();
      else await dispatch(createCourse({ ...payload, createdAt: todayISO() })).unwrap();
      navigate('/admin/courses', { state: { flash: `Course "${payload.title}" was saved.` } });
    } catch {
      setSaveError('Could not save the course. Please try again.');
      setSaving(false);
    }
  };

  if (loading) return <div className="text-center py-5"><Spinner animation="border" /></div>;
  if (notFound) return <Alert variant="danger" id="form-not-found">Course not found. <Link to="/admin/courses">Back to courses</Link></Alert>;

  const field = (name) => ({ name, value: form[name], onChange: handleChange, isInvalid: !!errors[name] });
  const feedback = (name) => <Form.Control.Feedback type="invalid" id={`${name}-error`}>{errors[name]}</Form.Control.Feedback>;

  return (
    <Card className="shadow-sm">
      <Card.Body>
        <h2 id="course-form-title" className="h4 mb-3">{isEdit ? 'Edit course' : 'Add a new course'}</h2>
        {saveError && <Alert variant="danger" id="save-error">{saveError}</Alert>}
        <Form id="course-form" noValidate onSubmit={handleSubmit}>
          <Form.Group className="mb-3" controlId="title">
            <Form.Label>Title</Form.Label>
            <Form.Control {...field('title')} />
            {feedback('title')}
          </Form.Group>
          <Row>
            <Form.Group as={Col} md={4} className="mb-3" controlId="categoryId">
              <Form.Label>Category</Form.Label>
              <Form.Select {...field('categoryId')}>
                <option value="">— Choose —</option>
                {categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
              </Form.Select>
              {feedback('categoryId')}
            </Form.Group>
            <Form.Group as={Col} md={4} className="mb-3" controlId="level">
              <Form.Label>Level</Form.Label>
              <Form.Select {...field('level')}>
                <option value="">— Choose —</option>
                {LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
              </Form.Select>
              {feedback('level')}
            </Form.Group>
            <Form.Group as={Col} md={4} className="mb-3" controlId="price">
              <Form.Label>Price (VND, 0 = free)</Form.Label>
              <Form.Control type="number" min="0" step="1000" {...field('price')} />
              {feedback('price')}
            </Form.Group>
          </Row>
          <Form.Group className="mb-3" controlId="instructor">
            <Form.Label>Instructor</Form.Label>
            <Form.Control {...field('instructor')} />
            {feedback('instructor')}
          </Form.Group>
          <Form.Group className="mb-3" controlId="description">
            <Form.Label>Description</Form.Label>
            <Form.Control as="textarea" rows={3} {...field('description')} />
            {feedback('description')}
          </Form.Group>
          <Form.Group className="mb-3" controlId="thumbnail">
            <Form.Label>Thumbnail URL (optional)</Form.Label>
            <Form.Control placeholder="https://…" {...field('thumbnail')} />
            {feedback('thumbnail')}
          </Form.Group>
          <Form.Check type="switch" id="published" name="published" label="Published (visible to students)" checked={form.published} onChange={handleChange} className="mb-3" />
          <div className="d-flex gap-2">
            <Button type="submit" id="save-course" disabled={saving}>{saving ? 'Saving…' : 'Save course'}</Button>
            <Link to="/admin/courses" id="cancel-course" className="btn btn-outline-secondary">Cancel</Link>
          </div>
        </Form>
      </Card.Body>
    </Card>
  );
}

// src/pages/admin/CurriculumPage.js — chương & bài học của MỘT khoá: thêm/xoá chương, thêm/sửa/xoá bài
// Dữ liệu chỉ dùng ở trang này ⇒ state cục bộ + courseApi (không cần đưa vào Redux)
import { useCallback, useEffect, useState } from 'react';
import { Alert, Button, Card, Col, Form, ListGroup, Row, Spinner } from 'react-bootstrap';
import { Link, useParams } from 'react-router-dom';
import courseApi from '../../api/courseApi';
import quizApi from '../../api/quizApi';
import { validateChapter, validateLesson } from '../../utils/validators';

const EMPTY_LESSON = { chapterId: '', title: '', videoUrl: '', duration: '', content: '' };
const nextOrder = (list) => list.reduce((m, x) => Math.max(m, x.order ?? 0), 0) + 1;

export default function CurriculumPage() {
  const { id } = useParams();
  const courseId = Number(id);
  const [course, setCourse] = useState(null);
  const [chapters, setChapters] = useState([]);
  const [status, setStatus] = useState('loading');
  const [chapterTitle, setChapterTitle] = useState('');
  const [chapterError, setChapterError] = useState('');
  const [lessonForm, setLessonForm] = useState(EMPTY_LESSON);
  const [lessonErrors, setLessonErrors] = useState({});
  const [editingLessonId, setEditingLessonId] = useState(null);
  const [message, setMessage] = useState('');

  // tải lại cả cây sau mỗi thay đổi — đơn giản và luôn khớp máy chủ
  const load = useCallback(async () => {
    try {
      const [c, chs] = await Promise.all([courseApi.getCourse(courseId), courseApi.getCurriculum(courseId)]);
      setCourse(c);
      setChapters(chs.map((ch) => ({ ...ch, lessons: (ch.lessons ?? []).slice().sort((a, b) => a.order - b.order) })));
      setStatus('succeeded');
    } catch {
      setStatus('failed');
    }
  }, [courseId]);

  useEffect(() => {
    load();
  }, [load]);

  const addChapter = async (e) => {
    e.preventDefault();
    const err = validateChapter(chapterTitle, chapters);
    setChapterError(err ?? '');
    if (err) return;
    await courseApi.createChapter({ courseId, title: chapterTitle.trim(), order: nextOrder(chapters) });
    setChapterTitle('');
    setMessage('Chapter added.');
    load();
  };

  const removeChapter = async (ch) => {
    if (!window.confirm(`Delete chapter "${ch.title}" and its ${ch.lessons.length} lesson(s)?`)) return;
    const questions = (await quizApi.getQuestions(ch.id)).map((q) => q.id);
    await courseApi.deleteMany('lessons', ch.lessons.map((l) => l.id));
    await courseApi.deleteMany('questions', questions);
    await courseApi.deleteChapter(ch.id);
    setMessage('Chapter deleted.');
    load();
  };

  const changeLesson = (e) => {
    const { name, value } = e.target;
    setLessonForm((f) => ({ ...f, [name]: value }));
    setLessonErrors((er) => ({ ...er, [name]: undefined }));
  };

  const editLesson = (lesson) => {
    setEditingLessonId(lesson.id);
    setLessonForm({ chapterId: String(lesson.chapterId), title: lesson.title, videoUrl: lesson.videoUrl, duration: String(lesson.duration), content: lesson.content });
    setLessonErrors({});
  };

  const cancelEdit = () => {
    setEditingLessonId(null);
    setLessonForm(EMPTY_LESSON);
    setLessonErrors({});
  };

  const saveLesson = async (e) => {
    e.preventDefault();
    const found = validateLesson(lessonForm);
    setLessonErrors(found);
    if (Object.keys(found).length > 0) return;
    const chapterId = Number(lessonForm.chapterId);
    const data = {
      chapterId,
      courseId,
      title: lessonForm.title.trim(),
      videoUrl: lessonForm.videoUrl.trim(),
      duration: Number(lessonForm.duration),
      content: lessonForm.content.trim(),
    };
    const target = chapters.find((c) => c.id === chapterId);
    const old = chapters.flatMap((c) => c.lessons).find((l) => l.id === editingLessonId);
    if (editingLessonId) {
      // đổi sang chương khác ⇒ xếp cuối chương mới
      await courseApi.updateLesson(editingLessonId, old && old.chapterId === chapterId ? data : { ...data, order: nextOrder(target.lessons) });
      setMessage('Lesson updated.');
    } else {
      await courseApi.createLesson({ ...data, order: nextOrder(target.lessons) });
      setMessage('Lesson added.');
    }
    cancelEdit();
    load();
  };

  const removeLesson = async (lesson) => {
    if (!window.confirm(`Delete lesson "${lesson.title}"?`)) return;
    await courseApi.deleteLesson(lesson.id);
    setMessage('Lesson deleted.');
    load();
  };

  if (status === 'loading') return <div className="text-center py-5"><Spinner animation="border" /></div>;
  if (status === 'failed') return <Alert variant="danger" id="curriculum-error">Course not found. <Link to="/admin/courses">Back</Link></Alert>;

  const lessonField = (name) => ({ name, value: lessonForm[name], onChange: changeLesson, isInvalid: !!lessonErrors[name] });
  const lessonFeedback = (name, key = name) => <Form.Control.Feedback type="invalid" id={`lesson-${key}-error`}>{lessonErrors[name]}</Form.Control.Feedback>;

  return (
    <>
      <Link to="/admin/courses" className="small">← Courses</Link>
      <h2 id="curriculum-title" className="h4 mt-2">Curriculum — {course.title}</h2>
      {message && <Alert variant="success" id="curriculum-success" dismissible onClose={() => setMessage('')}>{message}</Alert>}
      <Row className="g-4">
        <Col lg={7}>
          {chapters.length === 0 && <Alert variant="secondary" id="no-chapters">No chapters yet — add the first one.</Alert>}
          {chapters.map((ch, i) => (
            <Card key={ch.id} className="admin-chapter mb-3" id={`admin-chapter-${ch.id}`}>
              <Card.Header className="d-flex justify-content-between align-items-center">
                <span className="admin-chapter-title fw-semibold">Chapter {i + 1}: {ch.title}</span>
                <Button size="sm" variant="outline-danger" className="btn-delete-chapter" onClick={() => removeChapter(ch)}>Delete</Button>
              </Card.Header>
              <ListGroup variant="flush">
                {ch.lessons.map((l) => (
                  <ListGroup.Item key={l.id} className="admin-lesson d-flex justify-content-between align-items-center" id={`admin-lesson-${l.id}`}>
                    <span><span className="admin-lesson-title">{l.title}</span> <small className="text-muted">· {l.duration} min</small></span>
                    <span className="text-nowrap">
                      <Button size="sm" variant="outline-primary" className="btn-edit-lesson me-1" onClick={() => editLesson(l)}>Edit</Button>
                      <Button size="sm" variant="outline-danger" className="btn-delete-lesson" onClick={() => removeLesson(l)}>Delete</Button>
                    </span>
                  </ListGroup.Item>
                ))}
                {ch.lessons.length === 0 && <ListGroup.Item className="small text-muted">No lessons in this chapter.</ListGroup.Item>}
              </ListGroup>
            </Card>
          ))}
          <Form id="chapter-form" noValidate onSubmit={addChapter} className="d-flex gap-2 align-items-start">
            <div className="flex-grow-1">
              <Form.Control id="chapter-title" placeholder="New chapter title" value={chapterTitle} isInvalid={!!chapterError}
                onChange={(e) => { setChapterTitle(e.target.value); setChapterError(''); }} />
              <Form.Control.Feedback type="invalid" id="chapter-title-error">{chapterError}</Form.Control.Feedback>
            </div>
            <Button type="submit" id="add-chapter">Add chapter</Button>
          </Form>
        </Col>
        <Col lg={5}>
          <Card className="shadow-sm">
            <Card.Body>
              <h5 id="lesson-form-title">{editingLessonId ? 'Edit lesson' : 'Add a lesson'}</h5>
              <Form id="lesson-form" noValidate onSubmit={saveLesson}>
                <Form.Group className="mb-2" controlId="lesson-chapter">
                  <Form.Label>Chapter</Form.Label>
                  <Form.Select {...lessonField('chapterId')}>
                    <option value="">— Choose —</option>
                    {chapters.map((c, i) => <option key={c.id} value={c.id}>Chapter {i + 1}: {c.title}</option>)}
                  </Form.Select>
                  {lessonFeedback('chapterId', 'chapter')}
                </Form.Group>
                <Form.Group className="mb-2" controlId="lesson-title">
                  <Form.Label>Title</Form.Label>
                  <Form.Control {...lessonField('title')} />
                  {lessonFeedback('title')}
                </Form.Group>
                <Form.Group className="mb-2" controlId="lesson-video">
                  <Form.Label>YouTube URL</Form.Label>
                  <Form.Control placeholder="https://www.youtube.com/watch?v=…" {...lessonField('videoUrl')} />
                  {lessonFeedback('videoUrl', 'video')}
                </Form.Group>
                <Form.Group className="mb-2" controlId="lesson-duration">
                  <Form.Label>Duration (minutes)</Form.Label>
                  <Form.Control type="number" min="1" max="300" {...lessonField('duration')} />
                  {lessonFeedback('duration')}
                </Form.Group>
                <Form.Group className="mb-3" controlId="lesson-content">
                  <Form.Label>Content</Form.Label>
                  <Form.Control as="textarea" rows={3} {...lessonField('content')} />
                  {lessonFeedback('content')}
                </Form.Group>
                <div className="d-flex gap-2">
                  <Button type="submit" id="save-lesson">{editingLessonId ? 'Update lesson' : 'Add lesson'}</Button>
                  {editingLessonId && <Button variant="outline-secondary" id="cancel-edit" onClick={cancelEdit}>Cancel</Button>}
                </div>
              </Form>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </>
  );
}

// src/utils/courseQuery.js — lọc / tìm / sắp / phân trang danh sách khoá học: hàm THUẦN, không đụng state
export const LEVELS = ['Beginner', 'Intermediate', 'Advanced'];
export const PAGE_SIZE = 6;
export const SORTS = [
  ['newest', 'Newest first'],
  ['price-asc', 'Price: low to high'],
  ['price-desc', 'Price: high to low'],
  ['title', 'Title A → Z'],
];

// Đọc bộ lọc từ URL (?category=1&level=Beginner&price=free&q=react&sort=price-asc&page=2) — URL là nguồn sự thật
export function readFilters(searchParams) {
  return {
    category: searchParams.get('category') ?? '',
    level: searchParams.get('level') ?? '',
    price: searchParams.get('price') ?? '',
    q: searchParams.get('q') ?? '',
    sort: searchParams.get('sort') ?? 'newest',
    page: Number(searchParams.get('page')) || 1,
  };
}

const COMPARE = {
  newest: (a, b) => b.createdAt.localeCompare(a.createdAt),
  'price-asc': (a, b) => a.price - b.price,
  'price-desc': (a, b) => b.price - a.price,
  title: (a, b) => a.title.localeCompare(b.title),
};

export function applyCourseQuery(courses, { category, level, price, q, sort }) {
  const keyword = q.trim().toLowerCase();
  return courses
    // categoryId là SỐ, giá trị trên URL là CHUỖI ⇒ so bằng String()
    .filter((c) => !category || String(c.categoryId) === category)
    .filter((c) => !level || c.level === level)
    .filter((c) => !price || (price === 'free' ? c.price === 0 : c.price > 0))
    .filter((c) => !keyword || c.title.toLowerCase().includes(keyword) || c.instructor.toLowerCase().includes(keyword))
    .slice()                                  // sort() sửa mảng tại chỗ — sắp trên BẢN SAO
    .sort(COMPARE[sort] ?? COMPARE.newest);
}

// trang đã "kẹp" vào [1, totalPages] — URL ?page=99 không làm trang trắng
export function paginate(list, page, size = PAGE_SIZE) {
  const totalPages = Math.max(1, Math.ceil(list.length / size));
  const current = Math.min(Math.max(1, page), totalPages);
  return { items: list.slice((current - 1) * size, current * size), page: current, totalPages };
}

// src/utils/format.js — hàm THUẦN định dạng dữ liệu để hiển thị (dễ kiểm, dùng lại ở mọi trang)

// Ngày hôm nay "yyyy-mm-dd" theo giờ MÁY. Không dùng toISOString(): đó là giờ UTC — 6h sáng ở VN vẫn là "hôm qua".
export function todayISO() {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// 0 ⇒ "Free" · 199000 ⇒ "199.000 ₫" (dấu chấm ngăn cách hàng nghìn kiểu Việt Nam)
export function formatPrice(price) {
  const n = Number(price) || 0;
  if (n === 0) return 'Free';
  return `${String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.')} ₫`;
}

// "2026-09-01" hoặc "2026-09-01T10:30:00.000Z" ⇒ "01/09/2026" — cắt chuỗi, không qua new Date() nên không lệch múi giờ
export function formatDate(iso) {
  if (!iso) return '';
  const [y, m, d] = String(iso).slice(0, 10).split('-');
  return `${d}/${m}/${y}`;
}

// src/utils/learning.js — hàm THUẦN cho trang học
//   + chấm bài quiz

// Link YouTube "xem" (watch?v= / youtu.be/) KHÔNG nhúng được trong <iframe> (YouTube từ chối) ⇒ đổi sang /embed/<id>.
// Không nhận ra ⇒ '' (trang hiện "No video").
export function toEmbedUrl(url = '') {
  const m = String(url).match(/(?:youtube\.com\/(?:watch\?(?:.*&)?v=|embed\/)|youtu\.be\/)([\w-]{11})/);
  return m ? `https://www.youtube.com/embed/${m[1]}` : '';
}

// % hoàn thành, làm tròn số nguyên. Khoá chưa có bài ⇒ 0 (không chia cho 0 ra NaN)
export function calcProgress(doneCount, total) {
  return total > 0 ? Math.round((doneCount / total) * 100) : 0;
}

// Bài để "học tiếp": bài ĐẦU TIÊN chưa xong theo thứ tự; xong hết ⇒ bài đầu
export function resumeLesson(lessons, completedLessons) {
  return lessons.find((l) => !completedLessons.includes(l.id)) ?? lessons[0];
}

export const PASS_PERCENT = 70;

// answers: { [questionId]: chỉ số phương án đã chọn }
export function scoreQuiz(questions, answers) {
  const total = questions.length;
  const score = questions.filter((q) => answers[q.id] === q.answerIndex).length;
  const percent = total > 0 ? Math.round((score / total) * 100) : 0;
  return { score, total, percent, passed: percent >= PASS_PERCENT };
}

// src/utils/validators.js — luật kiểm dữ liệu form, viết THUẦN (nhận dữ liệu ⇒ trả { tênÔ: 'thông điệp' })
// Component chỉ việc gọi và hiện lỗi; một luật sửa ở một chỗ. Object rỗng = hợp lệ.
import { toEmbedUrl } from './learning';

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function checkEmail(email) {
  const v = email.trim();
  if (!v) return 'Email is required';
  if (!EMAIL_RE.test(v)) return 'Email is not valid';
  return null;
}

function checkPassword(password) {
  if (!password) return 'Password is required';
  if (password.length < 6) return 'Password must be at least 6 characters';
  return null;
}

// bỏ các ô không lỗi (null) ⇒ object chỉ còn lỗi thật
const clean = (errors) => Object.fromEntries(Object.entries(errors).filter(([, v]) => v));

export function validateLogin({ email, password }) {
  return clean({ email: checkEmail(email), password: checkPassword(password) });
}

export function validateRegister({ fullName, email, password, confirmPassword }) {
  return clean({
    fullName: fullName.trim().length < 3 ? 'Full name must be at least 3 characters' : null,
    email: checkEmail(email),
    password: checkPassword(password),
    confirmPassword: confirmPassword !== password ? 'Passwords do not match' : null,
  });
}

// Khoá học (thêm / sửa). allCourses để kiểm trùng tên; editingId = id đang sửa (được trùng với chính nó)
export function validateCourse(form, allCourses = [], editingId = null) {
  const title = form.title.trim();
  const price = String(form.price).trim();
  let titleError = null;
  if (title.length < 5 || title.length > 100) titleError = 'Title must be between 5 and 100 characters';
  else if (allCourses.some((c) => c.id !== editingId && c.title.trim().toLowerCase() === title.toLowerCase())) {
    titleError = 'A course with this title already exists';
  }
  let priceError = null;
  if (price === '') priceError = 'Price is required';
  else if (!/^\d+$/.test(price) || Number(price) > 10000000) priceError = 'Price must be a whole number between 0 and 10,000,000';
  return clean({
    title: titleError,
    categoryId: form.categoryId === '' ? 'Please choose a category' : null,
    level: form.level === '' ? 'Please choose a level' : null,
    price: priceError,
    instructor: form.instructor.trim() === '' ? 'Instructor is required' : null,
    description: form.description.trim().length < 20 ? 'Description must be at least 20 characters' : null,
    thumbnail: form.thumbnail.trim() && !/^https?:\/\/\S+$/.test(form.thumbnail.trim()) ? 'Thumbnail must be a valid http(s) URL' : null,
  });
}

export function validateChapter(title, chapters = []) {
  const t = title.trim();
  if (t.length < 3) return 'Chapter title must be at least 3 characters';
  if (chapters.some((c) => c.title.trim().toLowerCase() === t.toLowerCase())) return 'This chapter already exists';
  return null;
}

export function validateLesson(form) {
  const duration = String(form.duration).trim();
  return clean({
    chapterId: form.chapterId === '' ? 'Please choose a chapter' : null,
    title: form.title.trim().length < 3 ? 'Lesson title must be at least 3 characters' : null,
    videoUrl: toEmbedUrl(form.videoUrl.trim()) === '' ? 'Video must be a YouTube link (youtube.com/watch?v=… or youtu.be/…)' : null,
    duration: !/^\d+$/.test(duration) || Number(duration) < 1 || Number(duration) > 300 ? 'Duration must be a whole number of minutes (1-300)' : null,
    content: form.content.trim().length < 10 ? 'Content must be at least 10 characters' : null,
  });
}

export function validateQuestion(form) {
  const options = form.options.map((o) => o.trim());
  let optionsError = null;
  if (options.some((o) => o === '')) optionsError = 'All 4 options are required';
  else if (new Set(options.map((o) => o.toLowerCase())).size < options.length) optionsError = 'Options must be different';
  return clean({
    content: form.content.trim().length < 10 ? 'Question must be at least 10 characters' : null,
    options: optionsError,
    answer: form.answer === '' ? 'Please choose the correct answer' : null,
  });
}
